import * as React from "react";
import {type PiCardProps} from "@pihanga2/core";
import {Avatar, AvatarFallback, AvatarImage} from "@/components/ui/avatar";
import {cn} from "@/lib/utils";
import type {AvatarCardProps, AvatarSize} from "./avatar.types";

const SIZE_CLASS: Record<AvatarSize, string> = {
  sm: "size-6 text-xs",
  md: "size-8 text-xs",
  lg: "size-12 text-sm",
  xl: "size-16 text-base",
};

export const AvatarComponent = (
  props: PiCardProps<AvatarCardProps>,
): React.ReactNode => {
  const {src, alt = "", fallback, size = "md", className, cardName} = props;

  return (
    <Avatar className={cn(SIZE_CLASS[size], className)} data-pihanga={cardName}>
      {src && <AvatarImage src={src} alt={alt} />}
      <AvatarFallback>
        {fallback ?? alt.slice(0, 2).toUpperCase()}
      </AvatarFallback>
    </Avatar>
  );
};

import {createCardDeclaration} from "@pihanga2/core";

export const AVATAR_CARD = "shad/avatar";

export type AvatarSize = "sm" | "md" | "lg" | "xl";

export type AvatarCardProps = {
  src?: string;
  alt?: string;
  fallback?: string;
  size?: AvatarSize;
  className?: string;
};

export const ShadAvatar = createCardDeclaration<AvatarCardProps>(AVATAR_CARD);

import {registerCardComponent} from "@pihanga2/core";

import {AvatarComponent} from "./avatar.component";
import {AVATAR_CARD} from "./avatar.types";

export * from "./avatar.types";

registerCardComponent({
  name: AVATAR_CARD,
  component: AvatarComponent,
});
